#[inline]
pub unsafe fn ensureBits32(reader: *mut LodePNGBitReader, nbits: libc::size_t) {
    // helper to index into the data pointer like in C
    #[inline]
    unsafe fn get_byte(base: *const ::core::ffi::c_uchar, idx: libc::size_t) -> u32 {
        *base.add(idx) as u32
    }

    let reader_ref = &mut *reader;

    let start: libc::size_t = reader_ref.bp >> 3u32;
    let size: libc::size_t = reader_ref.size;

    if start + 4u32 as libc::size_t < size {
        let base = reader_ref.data;
        let mut buffer: u32 =
            get_byte(base, start + 0) |
            (get_byte(base, start + 1) << 8u32) |
            (get_byte(base, start + 2) << 16u32) |
            (get_byte(base, start + 3) << 24u32);

        buffer >>= (reader_ref.bp & 7u32 as libc::size_t) as u32;
        buffer |= (get_byte(base, start + 4) << 24u32)
            << (8u32 - (reader_ref.bp & 7u32 as libc::size_t) as u32);

        reader_ref.buffer = buffer as ::core::ffi::c_uint;
    } else {
        let base = reader_ref.data;
        let mut buffer: u32 = 0;

        if start + 0u32 as libc::size_t < size {
            buffer |= get_byte(base, start + 0);
        }
        if start + 1u32 as libc::size_t < size {
            buffer |= get_byte(base, start + 1) << 8u32;
        }
        if start + 2u32 as libc::size_t < size {
            buffer |= get_byte(base, start + 2) << 16u32;
        }
        if start + 3u32 as libc::size_t < size {
            buffer |= get_byte(base, start + 3) << 24u32;
        }

        buffer >>= (reader_ref.bp & 7u32 as libc::size_t) as u32;
        reader_ref.buffer = buffer as ::core::ffi::c_uint;
    }

    let _ = nbits;
}

fn search_code_index(array: *const u32, array_size: usize, value: usize) -> usize {
    unsafe {
        // binary search (only small gain over linear). TODO: use CPU log2 instruction for getting symbols instead
        let mut left: usize = 1;
        let mut right: usize = array_size.wrapping_sub(1);

        while left <= right {
            let mid: usize = (left + right) >> 1;
            if *array.add(mid) as usize >= value {
                right = mid.wrapping_sub(1);
            } else {
                left = left.wrapping_add(1);
            }
        }

        if left >= array_size || (*array.add(left) as usize) > value {
            left = left.wrapping_sub(1);
        }
        left
    }
}

#[inline]
unsafe fn getHash(
    data: *const libc::c_uchar,
    size: libc::size_t,
    pos: libc::size_t,
) -> libc::c_uint {
    let mut result: libc::c_uint = 0;
    if pos + 2 < size {
        result ^= (*(data.add(pos as usize)) as libc::c_uint) << 0u;
        result ^= (*(data.add(pos as usize + 1)) as libc::c_uint) << 4u;
        result ^= (*(data.add(pos as usize + 2)) as libc::c_uint) << 8u;
    } else {
        let mut amount: libc::size_t;
        let mut i: libc::size_t;
        if pos >= size {
            return 0;
        }
        amount = size - pos;
        i = 0;
        while i != amount {
            result
                ^= (*(data.add((pos + i) as usize)) as libc::c_uint)
                    << ((i as libc::c_uint) * 8u);
            i = i.wrapping_add(1);
        }
    }
    result & HASH_BIT_MASK
}

fn read_bit_from_reversed_stream(bitpointer: &mut libc::size_t, bitstream: *const u8) -> u8 {
    unsafe {
        let byte_index = (*bitpointer >> 3) as isize;
        let bit_index = 7 - (*bitpointer & 0x7);
        let byte = *bitstream.offset(byte_index);
        let result = ((byte >> bit_index) & 1) as u8;
        *bitpointer += 1;
        result
    }
}

use libc::size_t;

fn set_bit_of_reversed_stream(bitpointer: *mut size_t, bitstream: *mut u8, bit: u8) {
    unsafe {
        // Equivalent to: bitstream[(*bitpointer) >> 3u]
        let index = (*bitpointer >> 3) as isize;
        let ptr = bitstream.offset(index);

        let bit_pos = 7u8 - (((*bitpointer) & 7) as u8);

        if bit == 0 {
            // &= (unsigned char)(~(1u << (7u - ((*bitpointer) & 7u))));
            *ptr &= !(1u8 << bit_pos);
        } else {
            // |= (1u << (7u - ((*bitpointer) & 7u)));
            *ptr |= 1u8 << bit_pos;
        }

        *bitpointer += 1;
    }
}

pub fn check_color_validity(colortype: LodePNGColorType, bd: u32) -> u32 {
    match colortype {
        LodePNGColorType::LCT_GREY => {
            if !(bd == 1 || bd == 2 || bd == 4 || bd == 8 || bd == 16) {
                return 37;
            }
        }
        LodePNGColorType::LCT_RGB => {
            if !(bd == 8 || bd == 16) {
                return 37;
            }
        }
        LodePNGColorType::LCT_PALETTE => {
            if !(bd == 1 || bd == 2 || bd == 4 || bd == 8) {
                return 37;
            }
        }
        LodePNGColorType::LCT_GREY_ALPHA => {
            if !(bd == 8 || bd == 16) {
                return 37;
            }
        }
        LodePNGColorType::LCT_RGBA => {
            if !(bd == 8 || bd == 16) {
                return 37;
            }
        }
        LodePNGColorType::LCT_MAX_OCTET_VALUE => {
            return 31; // invalid color type
        }
        _ => {
            return 31; // invalid color type
        }
    }
    0 // allowed color type / bits combination
}

fn get_num_color_channels(colortype: LodePNGColorType) -> u32 {
    match colortype {
        LodePNGColorType::LCT_GREY => 1,
        LodePNGColorType::LCT_RGB => 3,
        LodePNGColorType::LCT_PALETTE => 1,
        LodePNGColorType::LCT_GREY_ALPHA => 2,
        LodePNGColorType::LCT_RGBA => 4,
        LodePNGColorType::LCT_MAX_OCTET_VALUE => 0, // invalid color type
        _ => 0, // invalid color type
    }
}

