    if colortype == LodePNGColorType::LCT_GREY {
        if chunkLength != 1 {
            return 114;
        }
        let d0 = byte_at(data, 0) as ::core::ffi::c_uint;
        if d0 == 0 || d0 > bitdepth {
            return 115;
        }
        info_ref.sbit_defined = 1;
        info_ref.sbit_r = d0;
        info_ref.sbit_g = d0;
        info_ref.sbit_b = d0;
    } else if colortype == LodePNGColorType::LCT_RGB
        || colortype == LodePNGColorType::LCT_PALETTE
    {
        if chunkLength != 3 {
            return 114;
        }
        let d0 = byte_at(data, 0) as ::core::ffi::c_uint;
        let d1 = byte_at(data, 1) as ::core::ffi::c_uint;
        let d2 = byte_at(data, 2) as ::core::ffi::c_uint;
        if d0 == 0 || d1 == 0 || d2 == 0 {
            return 115;
        }
        if d0 > bitdepth || d1 > bitdepth || d2 > bitdepth {
            return 115;
        }
        info_ref.sbit_defined = 1;
        info_ref.sbit_r = d0;
        info_ref.sbit_g = d1;
        info_ref.sbit_b = d2;
    } else if colortype == LodePNGColorType::LCT_GREY_ALPHA {
        if chunkLength != 2 {
            return 114;
        }
        let d0 = byte_at(data, 0) as ::core::ffi::c_uint;
        let d1 = byte_at(data, 1) as ::core::ffi::c_uint;
        if d0 == 0 || d1 == 0 {
            return 115;
        }
        if d0 > bitdepth || d1 > bitdepth {
            return 115;
        }
        info_ref.sbit_defined = 1;
        info_ref.sbit_r = d0;
        info_ref.sbit_g = d0;
        info_ref.sbit_b = d0;
        info_ref.sbit_a = d1;
    } else if colortype == LodePNGColorType::LCT_RGBA {
        if chunkLength != 4 {
            return 114;
        }
        let d0 = byte_at(data, 0) as ::core::ffi::c_uint;
        let d1 = byte_at(data, 1) as ::core::ffi::c_uint;
        let d2 = byte_at(data, 2) as ::core::ffi::c_uint;
        let d3 = byte_at(data, 3) as ::core::ffi::c_uint;
        if d0 == 0 || d1 == 0 || d2 == 0 || d3 == 0 {
            return 115;
        }
        if d0 > bitdepth || d1 > bitdepth || d2 > bitdepth || d3 > bitdepth {
            return 115;
        }
        info_ref.sbit_defined = 1;
        info_ref.sbit_r = d0;
        info_ref.sbit_g = d1;
        info_ref.sbit_b = d2;
        info_ref.sbit_a = d3;
    }
    0
}

fn is_gray_icc_profile(profile: *const u8, size: u32) -> u32 {
    unsafe {
        if size < 20 {
            return 0;
        }
        if *profile.add(16) == b'G'
            && *profile.add(17) == b'R'
            && *profile.add(18) == b'A'
            && *profile.add(19) == b'Y'
        {
            1
        } else {
            0
        }
    }
}

fn is_rgb_icc_profile(profile: *const u8, size: u32) -> u32 {
    // See comment in isGrayICCProfile
    if size < 20 {
        return 0;
    }

    unsafe {
        let p = profile;
        if *p.add(16) == b'R'
            && *p.add(17) == b'G'
            && *p.add(18) == b'B'
            && *p.add(19) == b' '
        {
            1
        } else {
            0
        }
    }
}
